from django.core.management.base import BaseCommand
from django.db import transaction
from apps.diccionario.models import Palabra, limpiar_termino

class Command(BaseCommand):
    help = 'Carga palabras masivamente en el diccionario Kichwa-Español'

    def add_arguments(self, parser):
        parser.add_argument(
            '--tipo',
            type=str,
            choices=['kichwa_espanol', 'espanol_kichwa', 'ambos'],
            default='ambos',
            help='Tipo de palabras a cargar (por defecto: ambos)'
        )
        parser.add_argument(
            '--limpiar',
            action='store_true',
            help='Limpiar todas las palabras antes de cargar nuevas'
        )

    def handle(self, *args, **options):
        tipo = options['tipo']
        limpiar = options['limpiar']

        if limpiar:
            self.stdout.write('🗑️ Limpiando palabras existentes...')
            Palabra.objects.all().delete()
            self.stdout.write(self.style.SUCCESS('✅ Palabras eliminadas'))

